(()=>{'use strict';const S=MartinsSupabaseConexao,$=id=>document.getElementById(id);let client=null,usedConfig=null,busy=false,auth=false,authorized=false,sync=null;const docUrls=[];const say=s=>$('sb-status').textContent=s;
function controls(){for(const element of document.querySelectorAll('#sb-fin-user input,#sb-fin-user button,#sb-fin-user select,#sb-fin-user textarea'))element.disabled=busy||!auth||element.dataset.finBlocked==='1';for(const id of ['sb-config','sb-url','sb-key','sb-email','sb-password','sb-negative-id','sb-hml-mode'])$(id).disabled=busy;$('sb-login').disabled=busy||!client;$('sb-logout').disabled=busy||!auth;$('sb-refresh-session').disabled=busy||!auth;$('sb-company').disabled=busy||!auth||$('sb-hml-mode').checked;$('sb-authorize').disabled=busy||!auth||$('sb-hml-mode').checked;$('sb-diagnose').disabled=busy||!authorized;$('sb-negative').disabled=busy||!authorized;}
function resetView(){financialReset();for(const url of docUrls.splice(0))URL.revokeObjectURL(url);if($('sb-doc-links'))$('sb-doc-links').replaceChildren();if($('sb-doc-file'))$('sb-doc-file').value='';if($('sb-doc-status'))$('sb-doc-status').textContent='';if($('sb-financial-status'))$('sb-financial-status').textContent='';sync?.reset();sync=null;if($('sb-hml-data'))$('sb-hml-data').value='{}';if($('sb-hml-status'))$('sb-hml-status').textContent='';for(const id of ['sb-hml-company','sb-hml-module','sb-hml-id'])if($(id))$(id).disabled=false;$('sb-results').replaceChildren();$('sb-company').replaceChildren();$('sb-user').textContent='';auth=false;authorized=false;}
async function run(fn){if(busy)return;busy=true;controls();try{await fn();}catch(e){say(e.message);if(!client?.state().empresaId)authorized=false;if(!client?.state().autenticado){resetView();}}finally{busy=false;controls();}}
$('sb-config').onclick=()=>run(async()=>{const candidate=S.config({url:$('sb-url').value,key:$('sb-key').value});client?.disconnect();client=S.create(candidate,{homologacao:$('sb-hml-mode').checked});usedConfig=candidate;resetView();$('sb-project').textContent='Projeto selecionado: '+new URL(candidate.url).hostname;say('Configuração pública validada localmente. Nenhuma conexão foi feita.');});
for(const id of ['sb-url','sb-key','sb-hml-mode'])$(id).oninput=()=>{client?.disconnect();client=null;usedConfig=null;resetView();$('sb-project').textContent='Configuração alterada: confirme antes de conectar.';controls();};
$('sb-login').onclick=()=>run(async()=>{if(!client||!usedConfig)throw Error('Confirme a configuração');resetView();const password=$('sb-password').value;try{const result=await client.signIn($('sb-email').value,password);auth=true;$('sb-user').textContent='Identidade confirmada no servidor: '+result.user.email;for(const p of result.profiles){const option=new Option(p.empresa_id+' · '+p.papel+(p.ativo?'':' (inativo)'),p.empresa_id);option.disabled=!p.ativo||p.papel!=='administrador';$('sb-company').add(option);}const first=result.profiles.find(p=>p.ativo&&p.papel==='administrador');if(first)$('sb-company').value=first.empresa_id;say($('sb-hml-mode').checked?'Identidade confirmada; use a conferência isolada de registros. Nenhum dado local foi enviado.':first?'Login real confirmado. Verifique a empresa antes de consultar.':'Login confirmado, mas nenhum perfil ativo de administrador foi liberado.');}finally{$('sb-password').value='';}});
$('sb-authorize').onclick=()=>run(async()=>{authorized=false;$('sb-results').replaceChildren();const result=await client.authorize($('sb-company').value);authorized=true;say('Função existente autorizou o administrador da empresa '+result.empresaId+'. Não foi executado SQL de alteração.');});$('sb-company').onchange=()=>{authorized=false;$('sb-results').replaceChildren();controls();say('Empresa alterada. Verifique a autorização novamente.');};
$('sb-diagnose').onclick=()=>run(async()=>{$('sb-results').replaceChildren();const report=await client.diagnose();for(const r of report.results){const tr=document.createElement('tr');for(const value of [r.tabela,r.status]){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('sb-results').append(tr);}say(report.observacao+'\nTabelas com consulta aceita: '+report.results.filter(r=>r.ok).length+'/'+report.results.length+'. RLS completa: pendente.');});
$('sb-negative').onclick=()=>run(async()=>{try{const result=await client.negative($('sb-negative-id').value.trim());say(result.observacao);}catch(e){authorized=false;throw e;}});$('sb-logout').onclick=()=>run(async()=>{const result=await client.signOut();resetView();say(result.servidor?'Sessão encerrada no servidor e nesta página.':'Sessão removida desta página; encerramento remoto não confirmado.');});
const provided=window.MARTINS_SUPABASE_PUBLIC_CONFIG;if(provided?.url||provided?.key){try{const c=S.config(provided);$('sb-url').value=c.url;$('sb-key').value=c.key;$('sb-project').textContent='Configuração pública preenchida pelo pacote; confirme para usar.';}catch{say('Configuração pública do pacote inválida. Informe os dados corretos.');}}controls();

$('sb-refresh-session').onclick=()=>run(async()=>{financialReset();sync?.reset();sync=null;authorized=false;const r=await client.refresh();auth=true;$('sb-user').textContent='Identidade renovada e reconferida no servidor: '+r.user.email;say('Sessão renovada somente em memória. Permissões serão reconferidas em cada operação.');});
const hml=document.createElement('section');hml.innerHTML='<h2>Conferência isolada de homologação</h2><p>Use somente dados sintéticos em projeto separado, com scripts e schema já conferidos. Não sincroniza automaticamente cadastros, folha ou dados existentes. Financeiro e vales não aceitam gravação genérica.</p><label>Empresa de homologação (UUID)<input id="sb-hml-company"></label><label>Módulo<select id="sb-hml-module"><option value="obras">Obras</option><option value="funcionarios">Funcionários</option><option value="frequencia">Frequência</option><option value="estoque">Estoque</option><option value="rdo">RDO</option></select></label><label>ID do registro (UUID)<input id="sb-hml-id"></label><button id="sb-hml-load" type="button">Carregar registro para conferência</button><label>Conteúdo sintético (objeto JSON)<textarea id="sb-hml-data" rows="8" style="box-sizing:border-box;width:100%">{}</textarea></label><button id="sb-hml-prepare" type="button">Preparar gravação</button><button id="sb-hml-save" type="button">Confirmar operação preparada / repetir mesmo ID</button><button id="sb-hml-reconcile" type="button">Conferir resultado incerto no servidor</button><p id="sb-hml-status" role="status"></p>';document.querySelector('main').append(hml);
$('sb-hml-load').onclick=()=>run(async()=>{if(!$('sb-hml-mode').checked||!client?.state().autenticado)throw Error('Configure projeto de homologação isolada e entre com usuário real de teste');if(sync?.snapshot().pendente)throw Error('Há operação preparada; confirme ou confira o resultado antes de carregar outra');sync=MartinsSincronizacaoHml.create(client,{empresaId:$('sb-hml-company').value.trim(),modulo:$('sb-hml-module').value,id:$('sb-hml-id').value.trim()});const row=await sync.load();$('sb-hml-data').value=JSON.stringify(row?.dados||{},null,2);$('sb-hml-status').textContent=row?'Registro carregado na versão '+row.versao:'Registro ausente; nova gravação terá versão 1.';});
$('sb-hml-prepare').onclick=()=>run(async()=>{if(!sync)throw Error('Carregue primeiro o registro');const state=sync.prepare(JSON.parse($('sb-hml-data').value));for(const id of ['sb-hml-company','sb-hml-module','sb-hml-id'])$(id).disabled=true;$('sb-hml-status').textContent='Operação '+state.pendente.operacao+' preparada sobre versão '+state.pendente.versao+'. Nenhuma gravação enviada.';});
$('sb-hml-save').onclick=()=>run(async()=>{if(!sync)throw Error('Prepare primeiro a operação');try{const result=await sync.save();for(const id of ['sb-hml-company','sb-hml-module','sb-hml-id'])$(id).disabled=false;$('sb-hml-status').textContent='Servidor confirmou versão '+result.versao+'. Auditoria e idempotência fazem parte da mesma transação.';}catch(e){$('sb-hml-status').textContent='Gravação não confirmada: '+sync.snapshot().status+'. ID preservado para repetição/conferência. '+e.message;throw e;}});
$('sb-hml-reconcile').onclick=()=>run(async()=>{if(!sync)throw Error('Não há conferência aberta');const result=await sync.reconcile();if(result.confirmado)for(const id of ['sb-hml-company','sb-hml-module','sb-hml-id'])$(id).disabled=false;$('sb-hml-status').textContent=result.confirmado?'Conteúdo e versão remotos correspondem à operação preparada.':'Conteúdo remoto não corresponde. Nenhuma sobrescrita foi feita; é necessária conferência.';});
for(const id of ['sb-hml-company','sb-hml-module','sb-hml-id'])$(id).addEventListener('input',()=>{sync?.reset();sync=null;$('sb-hml-status').textContent='Identificação alterada; carregue novamente antes de preparar.';});

const doc=document.createElement('section');doc.innerHTML='<h2>Documento privado de teste</h2><p>Use empresa e ID do documento informados na conferência de homologação. O nome original não entra no caminho remoto. Sem URL pública e sem sobrescrever arquivo existente.</p><label>Categoria de documento<select id="sb-doc-scope"><option value="funcionarios">Funcionário / RH</option><option value="financeiro">Financeiro</option></select></label><label>ID do objeto (UUID, preserve para conferir repetição)<input id="sb-doc-object"></label><label>Tipo<select id="sb-doc-extension"><option value="pdf">PDF</option><option value="png">PNG</option><option value="jpg">JPEG</option></select></label><label>Arquivo sintético, até 512 KB<input id="sb-doc-file" type="file" accept="application/pdf,image/png,image/jpeg"></label><button id="sb-doc-new" type="button">Gerar novo ID de objeto</button><button id="sb-doc-upload" type="button">Confirmar envio do arquivo de teste</button><button id="sb-doc-download" type="button">Baixar com autenticação para conferir</button><p id="sb-doc-status" role="status"></p><div id="sb-doc-links"></div>';document.querySelector('main').append(doc);
const docInput=()=>({escopo:$('sb-doc-scope').value,empresaId:$('sb-hml-company').value.trim(),id:$('sb-hml-id').value.trim(),objetoId:$('sb-doc-object').value.trim(),extensao:$('sb-doc-extension').value});
$('sb-doc-new').onclick=()=>{$('sb-doc-object').value=crypto.randomUUID();};
$('sb-doc-upload').onclick=()=>run(async()=>{if(!client)throw Error('Configure e autentique a homologação');const file=$('sb-doc-file').files?.[0];if(!file||file.size>524288)throw Error('Selecione arquivo de teste até 512 KB');const bytes=new Uint8Array(await file.arrayBuffer());const result=await client.uploadDocument(docInput(),bytes);$('sb-doc-status').textContent='Upload privado confirmado no caminho '+result.objeto+'. Não foi criada URL pública.';});
$('sb-doc-download').onclick=()=>run(async()=>{if(!client)throw Error('Configure e autentique a homologação');const result=await client.downloadDocument(docInput());for(const url of docUrls.splice(0))URL.revokeObjectURL(url);const url=URL.createObjectURL(new Blob([result.bytes],{type:result.mime}));docUrls.push(url);const a=document.createElement('a');a.href=url;a.download='documento-teste.'+$('sb-doc-extension').value;a.textContent='Baixar documento de teste autenticado';$('sb-doc-links').replaceChildren(a);$('sb-doc-status').textContent='Conteúdo recebido e tipo conferido. O link é temporário desta página.';});

const finance=document.createElement('section');finance.innerHTML='<h2>Estado financeiro no servidor</h2><p>Pagamentos, fechamentos e exceções de vales seguem bloqueados. Esta consulta não autoriza nem executa operação financeira.</p><button id="sb-financial-state" type="button">Conferir bloqueio no servidor de homologação</button><p id="sb-financial-status" role="status"></p>';document.querySelector('main').append(finance);
$('sb-financial-state').onclick=()=>run(async()=>{if(!client)throw Error('Configure e autentique a homologação');await client.financialStatus($('sb-hml-company').value.trim());$('sb-financial-status').textContent='Servidor confirmou: pagamentos bloqueados, fechamentos bloqueados e exceções de vales bloqueadas. Homologação real ainda pendente.';});

// Interface isolada: todos os registros e permissões vêm das APIs autenticadas; sem LocalStorage.
const financial=document.createElement('section');financial.id='sb-fin-user';financial.innerHTML=`<h2>Financeiro por usuário — homologação</h2><p>Lançador Financeiro: despesas e notas entram como Pendente de conferência. Nenhum pagamento, baixa ou conciliação é executado. Use somente dados fictícios. Requer scripts 001 a 007 no projeto separado.</p><label>Empresa (UUID)<input id="fu-company" autocomplete="off"></label><button id="fu-load" type="button">Consultar meus lançamentos autorizados</button><p id="fu-status" role="status" aria-live="polite"></p><form id="fu-form"><h3>Novo lançamento / edição</h3><p id="fu-editing">Novo lançamento</p><label>Tipo<select id="fu-type"><option value="despesa">Despesa</option><option value="nota_fiscal">Nota fiscal</option></select></label><label>Descrição<input id="fu-description" required maxlength="1000"></label><label>Valor (R$)<input id="fu-value" required inputmode="decimal" placeholder="0,00"></label><label>Data<input id="fu-date" type="date" required></label><label>Vencimento<input id="fu-due" type="date"></label><label>Número da nota / referência<input id="fu-number" maxlength="200"></label><label>Fornecedor<input id="fu-supplier" maxlength="200"></label><label>Conta como referência<select id="fu-account"><option value="">Sem conta</option></select></label><button type="submit">Salvar como Pendente de conferência</button><button id="fu-new" type="button">Iniciar novo lançamento</button></form><div style="overflow:auto"><table><thead><tr><th>Selecionar</th><th>Descrição / referência</th><th>Valor / estado</th><th>Autor / versão</th><th>Ação</th></tr></thead><tbody id="fu-rows"></tbody></table></div><details><summary>Documentos do lançamento autorizado</summary><label>Lançamento<select id="fu-doc-entry"></select></label><label>Arquivo PDF, PNG ou JPEG, até 512 KB<input id="fu-file" type="file" accept="application/pdf,image/png,image/jpeg"></label><label>ID do arquivo (UUID)<input id="fu-object" autocomplete="off"></label><label>Formato<select id="fu-extension"><option>pdf</option><option>png</option><option>jpg</option></select></label><button id="fu-upload" type="button">Anexar documento privado</button><button id="fu-download" type="button">Consultar documento autorizado</button><p id="fu-document"></p></details><details id="fu-admin" hidden><summary>Compartilhamento e contas — exclusivo do Master</summary><label>Usuários destinatários (seleção múltipla)<select id="fu-users" multiple size="4"></select></label><label><input id="fu-view" type="checkbox" checked> Visualizar lançamentos selecionados</label><label><input id="fu-edit" type="checkbox"> Editar enquanto pendentes</label><button id="fu-share" type="button">Aplicar compartilhamento / revogação</button><hr><label>Usuário da permissão de conta<select id="fu-account-user"></select></label><label>Conta<select id="fu-grant-account"></select></label><label><input id="fu-use-account" type="checkbox"> Usar conta como referência</label><label><input id="fu-own-account" type="checkbox" checked> Ver movimentos próprios / compartilhados</label><label><input id="fu-all-account" type="checkbox"> Ver todos os movimentos da conta</label><label><input id="fu-balance-account" type="checkbox"> Ver saldo da conta</label><button id="fu-grant-load" type="button">Carregar permissões atuais</button><button id="fu-grant" type="button">Confirmar permissões da conta</button><hr><label>Lançamento para conferência<select id="fu-review-entry"></select></label><label>Situação<select id="fu-review-state"><option value="conferido">Conferido</option><option value="bloqueado">Bloqueado</option><option value="pendente_conferencia">Reabrir conferência</option><option value="cancelado">Cancelado</option></select></label><label>Justificativa<input id="fu-reason" maxlength="1000"></label><button id="fu-review" type="button">Conferir sem pagar</button><button id="fu-audit" type="button">Consultar auditoria autorizada</button><pre id="fu-audit-result"></pre></details><button id="fu-balances" type="button">Consultar saldos expressamente autorizados</button><pre id="fu-balance-result"></pre>`;document.querySelector('main').append(financial);
const financialStyle=document.createElement('style');financialStyle.textContent='#sb-fin-user [hidden]{display:none!important}#sb-fin-user input[type=checkbox]{width:auto;display:inline}#sb-fin-user pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto}#sb-fin-user form{padding:12px;border:1px solid #cbd5e1;border-radius:10px}#sb-fin-user button{min-height:44px}#sb-fin-user table{min-width:760px}#sb-fin-user td{overflow-wrap:anywhere;max-width:220px}#sb-fin-user select[multiple]{min-height:120px}';document.head.append(financialStyle);
let financialSnapshot=null,financialEdit=null,financialOperation=null;const financialUrls=[];
function financialReset(){resetNfeUI();financialSnapshot=null;financialEdit=null;financialOperation=null;for(const url of financialUrls.splice(0))URL.revokeObjectURL(url);for(const id of ['fu-rows','fu-document','fu-audit-result','fu-balance-result','fu-status'])$(id)?.replaceChildren();$('fu-admin')?.setAttribute('hidden','');$('fu-form')?.reset();for(const id of ['fu-doc-entry','fu-users','fu-account-user','fu-grant-account'])$(id)?.replaceChildren();if($('fu-account'))$('fu-account').replaceChildren(new Option('Sem conta',''));if($('fu-editing'))$('fu-editing').textContent='Novo lançamento';if($('fu-file'))$('fu-file').value='';if($('fu-object'))$('fu-object').value='';}
function financialCompany(){const e=$('fu-company').value.trim();if(!S.uuid(e))throw Error('Informe empresa válida');return e;}
function financialRun(fn){run(async()=>{if(!client||!auth)throw Error('Entre no Supabase antes de usar o Financeiro');$('fu-status').textContent='Conferindo no servidor...';try{await fn();}catch(e){financialSnapshot=null;for(const url of financialUrls.splice(0))URL.revokeObjectURL(url);$('fu-document').replaceChildren();for(const id of ['fu-rows','fu-audit-result','fu-balance-result'])$(id).replaceChildren();$('fu-admin').hidden=true;$('fu-status').textContent=e.message;throw e;}});}
function financialOptions(id,rows,value,label){const select=$(id),old=select.value;select.replaceChildren();for(const r of rows)select.add(new Option(label(r),value(r)));if([...select.options].some(o=>o.value===old))select.value=old;}
async function financialLoad(){for(const url of financialUrls.splice(0))URL.revokeObjectURL(url);$('fu-document').replaceChildren();const e=financialCompany();$('fu-rows').replaceChildren();$('fu-audit-result').replaceChildren();$('fu-balance-result').replaceChildren();financialSnapshot=await client.financialRecords(e);$('fu-admin').hidden=!financialSnapshot.master;const {rows,accounts,users}=financialSnapshot;financialOptions('fu-account',[{id:'',nome:'Sem conta'},...accounts],r=>r.id,r=>r.nome);financialOptions('fu-grant-account',accounts,r=>r.id,r=>r.nome);for(const id of ['fu-users','fu-account-user'])financialOptions(id,users,r=>r.usuario_id,r=>r.usuario_id+' · '+r.papel);for(const id of ['fu-doc-entry','fu-review-entry'])financialOptions(id,rows,r=>r.id,r=>r.dados.descricao+' · '+r.estado);for(const r of rows){const tr=document.createElement('tr'),td=document.createElement('td'),check=document.createElement('input');check.type='checkbox';check.value=r.id;check.setAttribute('aria-label','Selecionar '+r.dados.descricao);td.append(check);tr.append(td);for(const value of [r.dados.descricao+' · '+(r.dados.documento_numero||''),(r.dados.valor_centavos/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})+' · '+r.estado,r.criado_por+' · v'+r.versao]){const cell=document.createElement('td');cell.textContent=value;tr.append(cell);}const action=document.createElement('td'),edit=document.createElement('button');edit.type='button';edit.textContent='Editar pendente';edit.disabled=r.estado!=='pendente_conferencia';if(edit.disabled)edit.dataset.finBlocked='1';edit.onclick=()=>{financialEdit={id:r.id,versao:r.versao,empresaId:e};financialOperation=null;for(const [id,key]of [['fu-type','tipo'],['fu-description','descricao'],['fu-date','data'],['fu-due','vencimento'],['fu-number','documento_numero'],['fu-supplier','fornecedor'],['fu-account','conta_id']])$(id).value=r.dados[key]||'';$('fu-value').value=(r.dados.valor_centavos/100).toFixed(2).replace('.',',');$('fu-editing').textContent='Editar '+r.id+' · v'+r.versao+'; o servidor reconferirá seu acesso';$('fu-form').scrollIntoView({block:'start'});};action.append(edit);tr.append(action);$('fu-rows').append(tr);}$('fu-status').textContent=rows.length+' lançamento(s) autorizado(s) pelo servidor. Sem consolidação financeira ou conciliação.';}
$('fu-load').onclick=()=>financialRun(financialLoad);$('fu-company').oninput=financialReset;
$('fu-new').onclick=()=>{financialEdit=null;financialOperation=null;$('fu-form').reset();$('fu-editing').textContent='Novo lançamento';};
$('fu-form').onsubmit=e=>{e.preventDefault();financialRun(async()=>{const empresaId=financialCompany();if(financialEdit&&financialEdit.empresaId!==empresaId)throw Error('Empresa alterada; recarregue o lançamento');const raw=$('fu-value').value.trim().replace(',','.');if(!/^\d+(?:\.\d{1,2})?$/.test(raw))throw Error('Valor deve ter até duas casas decimais');const value=Math.round(Number(raw)*100);if(!Number.isSafeInteger(value)||value<=0)throw Error('Valor inválido');const dados={tipo:$('fu-type').value,descricao:$('fu-description').value.trim(),valor_centavos:value,data:$('fu-date').value,vencimento:$('fu-due').value,documento_numero:$('fu-number').value,fornecedor:$('fu-supplier').value,conta_id:$('fu-account').value};const fingerprint=JSON.stringify({empresaId,edit:financialEdit,dados});if(!financialOperation||financialOperation.fingerprint!==fingerprint)financialOperation={fingerprint,id:financialEdit?.id||crypto.randomUUID(),operacao:crypto.randomUUID()};await client.saveFinancial({empresaId,id:financialOperation.id,operacao:financialOperation.operacao,versao:financialEdit?.versao||0,dados});financialOperation=null;financialEdit=null;$('fu-form').reset();$('fu-editing').textContent='Novo lançamento';await financialLoad();$('fu-status').textContent='Registrado como Pendente de conferência. Nenhum pagamento ou baixa executado.';});};
$('fu-share').onclick=()=>financialRun(async()=>{const ids=[...$('fu-rows').querySelectorAll('input:checked')].map(x=>x.value),usuarios=[...$('fu-users').selectedOptions].map(x=>x.value);await client.shareFinancial({empresaId:financialCompany(),ids,usuarios,visualizar:$('fu-view').checked,editar:$('fu-edit').checked});await financialLoad();$('fu-status').textContent='Compartilhamento/revogação confirmado pelo servidor e auditado.';});
$('fu-grant-load').onclick=()=>{const row=financialSnapshot?.grants.find(r=>r.conta_id===$('fu-grant-account').value&&r.usuario_id===$('fu-account-user').value);for(const [id,key,defaultValue]of [['fu-use-account','usar',false],['fu-own-account','movimentos_proprios',true],['fu-all-account','todos_movimentos',false],['fu-balance-account','saldo',false]])$(id).checked=row?row[key]:defaultValue;};
$('fu-grant').onclick=()=>financialRun(async()=>{await client.grantFinancialAccount({empresaId:financialCompany(),contaId:$('fu-grant-account').value,usuarioId:$('fu-account-user').value,usar:$('fu-use-account').checked,proprios:$('fu-own-account').checked,todos:$('fu-all-account').checked,saldo:$('fu-balance-account').checked});await financialLoad();$('fu-status').textContent='Permissões independentes confirmadas e auditadas pelo servidor.';});
$('fu-review').onclick=()=>financialRun(async()=>{const r=financialSnapshot?.rows.find(x=>x.id===$('fu-review-entry').value);if(!r)throw Error('Recarregue o lançamento');await client.reviewFinancial({empresaId:financialCompany(),id:r.id,versao:r.versao,estado:$('fu-review-state').value,motivo:$('fu-reason').value});await financialLoad();$('fu-status').textContent='Conferência registrada. Não representa pagamento.';});
$('fu-balances').onclick=()=>financialRun(async()=>{const rows=await client.financialBalances(financialCompany());$('fu-balance-result').textContent=rows.length?rows.map(r=>r.conta_id+': '+(r.saldo_centavos/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})).join('\n'):'Nenhum saldo autorizado para este usuário.';$('fu-status').textContent='Consulta limitada pelas permissões de saldo no servidor.';});
$('fu-audit').onclick=()=>financialRun(async()=>{$('fu-audit-result').textContent=JSON.stringify(await client.financialAudit(financialCompany()),null,2);$('fu-status').textContent='Auditoria consultada com RLS.';});
function financialDocumentInput(){return {empresaId:financialCompany(),id:$('fu-doc-entry').value,objetoId:$('fu-object').value.trim(),extensao:$('fu-extension').value};}
$('fu-upload').onclick=()=>financialRun(async()=>{const file=$('fu-file').files[0];if(!file||file.size>524288)throw Error('Selecione arquivo de até 512 KB');if(!$('fu-object').value)$('fu-object').value=crypto.randomUUID();const result=await client.uploadFinancialDocument(financialDocumentInput(),new Uint8Array(await file.arrayBuffer()));$('fu-document').textContent='Documento privado registrado: '+result.objeto;$('fu-status').textContent='Upload confirmado; arquivo não é público e não pode ser sobrescrito.';});
$('fu-download').onclick=()=>financialRun(async()=>{for(const url of financialUrls.splice(0))URL.revokeObjectURL(url);$('fu-document').replaceChildren();const r=await client.downloadFinancialDocument(financialDocumentInput()),url=URL.createObjectURL(new Blob([r.bytes],{type:r.mime})),link=document.createElement('a');financialUrls.push(url);link.href=url;link.download=$('fu-object').value+'.'+$('fu-extension').value;link.textContent='Baixar documento autorizado';$('fu-document').append(link);$('fu-status').textContent='Permissão e arquivo reconferidos no servidor.';});

const nfeUI=document.createElement('section');nfeUI.id='nfi-panel';nfeUI.innerHTML='<h3>NF-e → Recebimento e Contas a Pagar — contrato isolado</h3><p>Exclusivo do Master nesta etapa. Evidências fiscais devem vir do serviço confiável; a tela não declara assinatura válida. Normal: confirma estoque e parcelas pendentes na mesma transação. Complementares, devoluções e canceladas permanecem bloqueadas para tratamento fiscal específico. Nenhum pagamento ou conciliação.</p><button id="nfi-load" type="button">Consultar notas e pedidos provisionados no servidor</button><label>Nota<select id="nfi-note"></select></label><label>Depósito<select id="nfi-depot"></select></label><p id="nfi-info"></p><div id="nfi-items"></div><div id="nfi-parcels"></div><label>Identificação da entrega / documento<input id="nfi-document" maxlength="200"></label><button id="nfi-confirm" type="button">Conferir e confirmar transação — sem pagar</button><details><summary>Conferência do pedido e de obrigações antigas</summary><p>Selecione no quadro financeiro os lançamentos que já representam esta compra. Não identificar obrigação existente pode causar duplicidade: confira a documentação antes de confirmar. Pedidos legados continuam sem entrada retroativa, mesmo após esta conferência.</p><label>Justificativa / identificação da documentação<input id="nfi-reason" maxlength="1000"></label><button id="nfi-review" type="button">Registrar conferência do pedido e vínculos selecionados</button></details><p id="nfi-status" role="status"></p>';$('fu-admin').append(nfeUI);let nfeServer=null,nfeOperation=null;
function resetNfeUI(){nfeServer=null;nfeOperation=null;for(const id of ['nfi-note','nfi-depot','nfi-info','nfi-items','nfi-parcels','nfi-status'])$(id)?.replaceChildren();for(const id of ['nfi-document','nfi-reason'])if($(id))$(id).value='';}
function renderNfeUI(){const note=nfeServer?.nfe_notas.find(n=>n.chave===$('nfi-note').value),order=nfeServer?.nfe_pedidos.find(p=>p.id===note?.pedido_id);$('nfi-items').replaceChildren();$('nfi-parcels').replaceChildren();if(!note)return;$('nfi-info').textContent=note.fornecedor+' · pedido '+(order?.referencia_origem||note.pedido_id)+' · '+note.finalidade+' · situação fiscal registrada: '+note.situacao+' · consulta oficial: '+(note.consulta_oficial?'registrada no servidor':'NÃO REALIZADA')+' · '+(note.teste_sintetico?'EVIDÊNCIA SINTÉTICA DE TESTE':'Evidência de servidor; confiança deve estar aprovada')+' · pedido '+(order?.conferido?'conferido':'aguarda conferência');for(const item of note.itens){const l=document.createElement('label');l.textContent='Receber item '+item.nItem+' · '+item.quantidade+' '+item.unidade+' na nota';const q=document.createElement('input');q.type='number';q.min='0';q.step='0.000001';q.dataset.nItem=item.nItem;q.setAttribute('aria-label','Receber item '+item.nItem);l.append(q);$('nfi-items').append(l);}for(const p of note.parcelas){const l=document.createElement('label');l.textContent='Parcela '+p.numero+' · '+(p.valorCentavos/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})+' · '+p.vencimento;const select=document.createElement('select');select.dataset.numero=p.numero;select.add(new Option('Criar pendente somente se não houver obrigação existente',''));for(const f of financialSnapshot?.rows||[])select.add(new Option(f.dados.descricao+' · '+(f.dados.valor_centavos/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),f.id));l.append(select);$('nfi-parcels').append(l);}}
$('nfi-load').onclick=()=>financialRun(async()=>{nfeServer=await client.nfeContext(financialCompany());financialOptions('nfi-note',nfeServer.nfe_notas,n=>n.chave,n=>n.chave+' · '+n.fornecedor);financialOptions('nfi-depot',nfeServer.nfe_depositos.filter(d=>d.ativo),d=>d.id,d=>d.nome);renderNfeUI();$('nfi-status').textContent='Dados carregados do servidor; nenhuma transação executada.';$('fu-status').textContent='Contrato NF-e carregado.';});$('nfi-note').onchange=()=>{nfeOperation=null;renderNfeUI();};
$('nfi-confirm').onclick=()=>financialRun(async()=>{const input={empresaId:financialCompany(),chave:$('nfi-note').value,depositoId:$('nfi-depot').value,documento:$('nfi-document').value,itens:[...$('nfi-items').querySelectorAll('input')].filter(i=>Number(i.value)>0).map(i=>({nItem:i.dataset.nItem,quantidade:i.value})),vinculos:[...$('nfi-parcels').querySelectorAll('select')].filter(s=>s.value).map(s=>({numero:s.dataset.numero,lancamentoId:s.value}))};if(!confirm('Confirmar recebimento e parcelas PENDENTES DE CONFERÊNCIA? Nenhum pagamento ou baixa será executado.')){$('fu-status').textContent='Conferência cancelada sem envio.';return;}const fingerprint=JSON.stringify(input);if(!nfeOperation||nfeOperation.fingerprint!==fingerprint)nfeOperation={fingerprint,id:crypto.randomUUID()};const result=await client.integrateNfe({...input,operacao:nfeOperation.id});nfeOperation=null;await financialLoad();$('nfi-status').textContent='Transação confirmada: recebimento '+result.recebimento+' e '+result.parcelas.length+' parcela(s) pendente(s). Sem pagamento. '+(result.teste_sintetico?'VALIDAÇÃO COM EVIDÊNCIA SINTÉTICA; sem homologação fiscal real.':'Situação fiscal: '+result.situacao_fiscal);$('fu-status').textContent='Recebimento e financeiro confirmados na mesma transação.';});
$('nfi-review').onclick=()=>financialRun(async()=>{const note=nfeServer?.nfe_notas.find(n=>n.chave===$('nfi-note').value),order=nfeServer?.nfe_pedidos.find(p=>p.id===note?.pedido_id);if(!order)throw Error('Carregue e identifique o pedido');const origens=[...$('fu-rows').querySelectorAll('input:checked')].map(i=>i.value);await client.reviewNfeOrder({empresaId:financialCompany(),pedidoId:order.id,versao:order.versao,origens,motivo:$('nfi-reason').value});nfeServer=await client.nfeContext(financialCompany());renderNfeUI();$('nfi-status').textContent='Conferência auditada; nenhum ajuste de estoque ou pagamento realizado.';$('fu-status').textContent='Pedido conferido no servidor.';});
controls();
})();

